SELECT COUNT(*)
FROM Invoice i JOIN Customer c ON c.CustomerId = i.CustomerId
WHERE c.Country IN ('Brazil', 'Argentina', 'Chile');

SELECT UnitPrice, COUNT(*) AS Downloads
FROM InvoiceLine
GROUP BY UnitPrice;

SELECT ROUND(AVG(energy), 3)
FROM songs s JOIN artists a ON a.id = s.artist_id
WHERE a.name = 'Post Malone';

SELECT a.name, COUNT(*) AS n
FROM songs s JOIN artists a ON a.id = s.artist_id
GROUP BY a.name ORDER BY n DESC LIMIT 1;

SELECT ROUND(AVG(rating), 2)
FROM ratings r JOIN movies m ON m.id = r.movie_id
WHERE m.year = 2013;

SELECT COUNT(*) FROM stars
WHERE movie_id = (SELECT id FROM movies
                  WHERE title = 'Harry Potter and the Sorcerer''s Stone');

SELECT COUNT(DISTINCT s.person_id)
FROM stars s JOIN movies m ON m.id = s.movie_id
WHERE m.year = 2003;

SELECT COUNT(DISTINCT d.person_id)
FROM directors d JOIN ratings r ON r.movie_id = d.movie_id
WHERE r.rating >= 8.0;

SELECT COUNT(DISTINCT person_id) FROM stars
WHERE movie_id IN (
  SELECT movie_id FROM stars
  WHERE person_id = (SELECT id FROM people WHERE name = 'Kevin Bacon' AND birth = 1958)
)
AND person_id <> (SELECT id FROM people WHERE name = 'Kevin Bacon' AND birth = 1958);

SELECT description FROM crime_scene_reports
WHERE year = 2020 AND month = 7 AND day = 28
  AND street = 'Chamberlin Street';

SELECT ROUND(SUM(Amount), 2) AS TotalReturns2014Q1
FROM pcards
WHERE Amount < 0 AND Month BETWEEN 1 AND 3;

SELECT COUNT(*) FROM (
  SELECT FullName FROM pcards
  GROUP BY FullName
  HAVING COUNT(*) > 10
);

SELECT COUNT(*) FROM (
  SELECT FullName, Month FROM pcards
  GROUP BY FullName, Month
  HAVING SUM(Amount) > 10000
);

SELECT COUNT(*) FROM (
  SELECT FullName, Vendor, TransactionDate
  FROM pcards
  GROUP BY FullName, Vendor, TransactionDate
  HAVING COUNT(*) > 1 AND SUM(Amount) > 5000
);
